"""Build the local, reviewable External Language Education website."""
from pathlib import Path
from html import escape
import json

ROOT = Path(__file__).resolve().parent
LANGUAGES = json.loads((ROOT / 'content.json').read_text())
PHOTO = 'assets/photos/blue/'
NAV = [('languages.html','Языки'),('format.html','Обучение'),('admission.html','Поступление'),('tuition.html','Стоимость'),('schedule.html','Расписание')]

def icon(name='arrow'):
    paths={'arrow':'<path d="M4 12h15m-6-6 6 6-6 6"/>','plus':'<path d="M12 5v14M5 12h14"/>','menu':'<path d="M4 8h16M4 16h16"/>','check':'<path d="m5 12 4 4L19 6"/>','pin':'<path d="M19 10c0 5-7 11-7 11s-7-6-7-11a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>','clock':'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>','globe':'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>','chevron':'<path d="m9 5 7 7-7 7"/>'}
    return f'<svg viewBox="0 0 24 24" aria-hidden="true">{paths[name]}</svg>'
ARROW=icon()
BRAND='<a class="brand" href="index.html" aria-label="External Language Education — главная"><span class="brand-word">external<span class="brand-dot">.</span></span><span class="brand-line">LANGUAGE EDUCATION</span></a>'

def button(label,href='#application',kind='',extra=''):
    return f'<a class="button {kind}" href="{href}" {extra}>{label}{ARROW}</a>'

def photo(src,alt,cls='',caption=None,eager=False):
    return f'<figure class="photo {cls}"><img src="{src}" alt="{alt}" width="1536" height="1024" {"fetchpriority=high" if eager else "loading=lazy"}>'+ (f'<figcaption>{caption}</figcaption>' if caption else '')+'</figure>'

def header(page):
    links=''.join(f'<a href="{href}"'+(' aria-current="page"' if href==page else '')+f'>{label}</a>' for href,label in NAV)
    return f'''<a class="skip-link" href="#main">Перейти к содержимому</a><header class="site-header"><div class="shell header-inner">{BRAND}<nav class="desktop-nav" aria-label="Основная навигация">{links}</nav><a class="header-contact" href="#application">Связаться {ARROW}</a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="mobile-navigation">Меню {icon('menu')}</button></div><nav class="mobile-nav" id="mobile-navigation" aria-label="Мобильная навигация" hidden><a href="index.html">Главная</a>{links}<a href="interview.html">Пробный урок</a><a href="#application">Связаться со школой</a></nav></header>'''

def footer():
    return f'''<footer class="site-footer"><div class="shell footer-grid"><div>{BRAND}<p>Иностранные языки экстерном.<br>Учимся в Москва-Сити.<br>Говорим с целым миром.</p></div><div><h3>Школа</h3><a href="format.html">Как мы учимся</a><a href="admission.html">Поступление</a><a href="interview.html">Собеседование и пробный урок</a><a href="schedule.html">Расписание</a><a href="tuition.html">Стоимость и оплата</a></div><div><h3>Языки</h3>{''.join(f'<a href="{l["slug"]}.html">{l["name"]}</a>' for l in LANGUAGES)}</div><div><h3>Начнём с разговора</h3><p>Расскажите о своей цели.<br>Поможем выбрать следующий шаг.</p>{button('Оставить заявку',kind='button-small')}<p class="footer-place">{icon('pin')} Москва-Сити</p></div></div><div class="shell footer-bottom"><span>© 2026 External Language Education</span><span>Визуальная версия для согласования</span><a href="#main">Наверх ↑</a></div></footer>'''

def application(language=None):
    opts='<option value="" disabled'+(' selected' if not language else '')+'>Выберите язык</option>'+''.join(f'<option'+(' selected' if language==l['name'] else '')+f'>{l["name"]}</option>' for l in LANGUAGES)+'<option>Помогите выбрать</option>'
    return f'''<section class="contact-section" id="application" aria-labelledby="application-heading"><div class="shell contact-grid"><div class="contact-copy"><h2 id="application-heading">У вас есть цель.<br><span>У нас — ваш<br>следующий шаг.</span></h2><p>Переезд, поступление, работа или давняя мечта заговорить. Расскажите, что важно именно вам — обсудим цель, сроки и подходящий формат.</p><div class="contact-location">{icon('pin')} Очное обучение в Москва-Сити</div><div class="contact-photo"><img src="{PHOTO}study-detail.jpg" alt="Иллюстрация совместной работы с языком" width="1536" height="1024" loading="lazy"><span>Знакомство — первый шаг к вашей программе</span></div></div><form class="application-form" aria-label="Заявка на обучение" novalidate><div class="form-fields"><h3>Давайте познакомимся</h3><p class="form-intro">Оставьте контакты для разговора со школой.</p><div class="form-selection" hidden><span data-selection-text></span><button class="clear-selection" type="button">Сбросить</button></div><div class="field"><label for="name">Как вас зовут?</label><input id="name" autocomplete="given-name" placeholder="Ваше имя" required maxlength="80" aria-describedby="name-error"><p class="form-error" id="name-error" role="alert" hidden></p></div><div class="field"><label for="phone">Телефон</label><input id="phone" type="tel" autocomplete="tel" placeholder="+7 ___ ___ __ __" required maxlength="25" aria-describedby="phone-error"><p class="form-error" id="phone-error" role="alert" hidden></p></div><div class="field"><label for="language">Какой язык хотите изучать?</label><select id="language" required aria-describedby="language-error">{opts}</select><p class="form-error" id="language-error" role="alert" hidden></p></div><div class="field"><label for="comment">Ваша цель или вопрос <span>необязательно</span></label><textarea id="comment" maxlength="1000" placeholder="Например, планирую учёбу в Италии через полгода"></textarea></div><button class="button" type="submit"><span>Оставить заявку</span>{ARROW}</button><p class="form-note">Демонстрационная форма: данные никуда не отправляются.</p></div><div class="form-status" role="status" tabindex="-1" hidden><div class="status-symbol">{icon('check')}</div><h3>Всё готово<br>для знакомства</h3><p>Так будет выглядеть подтверждение. В этой демонстрационной версии данные не отправлены в школу.</p><button class="button form-reset" type="button">Заполнить ещё раз {ARROW}</button></div></form></div></section>'''

def faq(items,title='То, что хочется уточнить'):
    return f'<section class="shell section faq-layout"><div><h2>{title}</h2><p>Не нашли свой вопрос?<br>Обсудим его при знакомстве.</p><a class="text-link" href="#application">Задать вопрос {ARROW}</a></div><div class="faq-list">'+''.join(f'<details><summary>{q}{icon("plus")}</summary><div class="faq-answer"><p>{a}</p></div></details>'for q,a in items)+'</div></section>'

GENERAL_FAQ=[('Можно ли начать с нуля?','Да. Мы подбираем группу по текущему уровню и возрасту. На знакомстве определим вашу точку старта, обсудим цель и готовность к интенсивному ритму.'),('За сколько я выучу язык?','Срок зависит от вашей цели, исходного уровня и выбранного языка. После знакомства и диагностики мы предложим конкретную программу. Единого срока для всех нет.'),('Где проходят занятия?','Групповые занятия проходят очно в Москва-Сити. Пробный урок — онлайн, один на один с преподавателем. Детали встречи сообщит специалист школы.'),('Нужно ли оплачивать весь курс сразу?','Нет. Можно выбрать оплату раз в неделю, раз в две недели или за четыре учебные недели. Выбранный период фиксируется в договоре.'),('Можно ли сначала познакомиться с преподавателем?','Да. До решения об обучении вы проходите индивидуальный онлайн-урок с преподавателем. Это возможность оценить его подход и собственные ощущения от занятий.')]

def section_title(title,copy='',link=None):
    return f'<div class="section-heading"><h2>{title}</h2><div>'+ (f'<p>{copy}</p>' if copy else '')+(f'<a class="text-link" href="{link[0]}">{link[1]} {ARROW}</a>' if link else '')+'</div></div>'

def language_card(l):
    region='asia' if l['slug'] in ['chinese','korean'] else 'europe'
    return f'''<a class="language-card" href="{l['slug']}.html" data-region="{region}"><div class="language-image"><img src="{l['photo']}" alt="{l['place']}" width="920" height="880" loading="lazy"><span>{l['country']}</span></div><div class="language-card-body"><h3>{l['name']}</h3><p>{l['lead']}</p><span class="card-link">О программе {ARROW}</span></div></a>'''

def languages_section(full=False):
    return '<section class="shell section" id="languages">'+section_title('Куда вас приведёт<br>новый язык?','Семь языков — для вашей следующей главы. У каждого своя программа и свой преподаватель.')+'<div class="language-filters" role="group" aria-label="Показать языки"><button class="filter-button" data-filter="all" aria-pressed="true">Все языки <span>7</span></button><button class="filter-button" data-filter="europe" aria-pressed="false">Европейские</button><button class="filter-button" data-filter="asia" aria-pressed="false">Азиатские</button></div><div class="language-grid">'+''.join(language_card(l)for l in LANGUAGES)+'</div><p class="section-note">Не уверены, с чего начать? <a href="#application">Обсудим ваши планы и поможем выбрать программу.</a></p></section>'

def format_feature():
    return f'''<section class="blue-section round-section"><div class="shell section"><div class="feature-heading"><h2>Больше языка<br>в вашей жизни.</h2><p>Интенсив — это время на настоящую практику. Вы разбираете тему, сразу пробуете её в диалоге и закрепляете в речи.</p></div><div class="practice-grid">{photo(PHOTO+'group-practice.jpg','Иллюстрация разговорной практики в небольшой взрослой группе','practice-photo','Иллюстрация учебного формата')}<div class="practice-content"><div class="large-equation">4 × 4<span>часа в день · дня в неделю</span></div><p>16 часов живой языковой практики каждую неделю. Достаточно времени, чтобы пройти полный цикл: понять, попробовать, заговорить и закрепить.</p><ul class="check-list"><li>{icon('check')} Небольшая группа — до 8 человек</li><li>{icon('check')} Подбор по возрасту и уровню</li><li>{icon('check')} Работа в парах и живые обсуждения</li><li>{icon('check')} 30 минут на перерыв и общение</li></ul>{button('Как устроено обучение','format.html','button-white')}</div></div><div class="day-flow"><div><b>Понимаем</b><p>Разбираем новую тему и её смысл.</p></div><div><b>Пробуем</b><p>Применяем материал в заданиях.</p></div><div><b>Говорим</b><p>Общаемся в парах и всей группой.</p></div><div><b>Закрепляем</b><p>Повторяем, обсуждаем и разбираем ошибки.</p></div></div></div></section>'''

def schedule_cards():
    return f'''<section class="shell section" id="times">{section_title('У вашего дня<br>есть место для языка.','Выберите утро или вечер. Точные дни занятий и место в группе обсудим при поступлении.')}<div class="time-grid"><a class="time-card" href="schedule.html?time=morning"><img src="assets/photos/approved/classroom.jpg" alt="Иллюстрация светлого учебного пространства" width="1536" height="1024" loading="lazy"><div class="time-card-content"><h3>Утро</h3><strong>9:00–13:30</strong><p>Начните день с погружения в язык.<br>После занятия — время для других планов.</p><span class="time-link">Выбрать утро {ARROW}</span></div></a><a class="time-card" href="schedule.html?time=evening"><img src="assets/photos/approved/moscow-evening.jpg" alt="Вечерний вид на Москва-Сити" width="1536" height="1024" loading="lazy"><div class="time-card-content"><h3>Вечер</h3><strong>17:30–22:00</strong><p>Сохраните привычное утро.<br>Посвятите вторую половину дня языку.</p><span class="time-link">Выбрать вечер {ARROW}</span></div></a></div><p class="section-note">В каждом окне — 4 часа обучения и 30 минут перерыва. Иллюстрации передают атмосферу занятий.</p></section>'''

def calculator():
    return f'''<div class="calculator"><div><h2>Понятная цена.<br>Удобный ритм оплаты.</h2><p>900 ₽ за час. Без предоплаты за весь курс. Вы выбираете период оплаты — и он закрепляется в договоре.</p><a class="text-link" href="tuition.html#price-table">Посмотреть все расчёты {ARROW}</a></div><div class="calculator-box"><div class="cadence-controls" role="group" aria-label="Период оплаты"><button class="cadence-button" data-cadence="week" aria-pressed="true">Неделя</button><button class="cadence-button" data-cadence="fortnight" aria-pressed="false">Две недели</button><button class="cadence-button" data-cadence="month" aria-pressed="false">Четыре недели</button></div><div class="price-live" aria-live="polite"><div class="calculator-price" data-price>14 400 ₽</div><div class="calculator-period" data-price-period>/ неделя</div><p data-price-description>16 часов · 4 учебных дня</p></div>{button('Обсудить обучение')}<p class="calculator-note">Цена часа одинакова для любого периода.</p></div></div>'''

def admissions_steps():
    steps=[('Ваша цель','Обсудим, для чего нужен язык и к какому сроку вы хотите прийти к результату.'),('Ваша точка старта','Определим текущий уровень и подходящую группу, познакомим со школой.'),('Ваш преподаватель','Проведём индивидуальное онлайн-занятие — вы оцените подход на своём опыте.'),('Ваше решение','Согласуем программу, расписание и оплату. Все условия закрепим в договоре.')]
    return '<div class="admission-steps">'+''.join(f'<article><span class="step-number">0{i}</span><h3>{t}</h3><p>{p}</p></article>'for i,(t,p)in enumerate(steps,1))+'</div>'

def innerhero(title,lead,image,alt,links,caption=''):
    return f'''<div class="shell breadcrumb"><a href="index.html">Главная</a><span>/</span><span>{title.replace('<br>',' ')}</span></div><section class="shell inner-hero"><div class="inner-hero-copy"><h1>{title}</h1><p>{lead}</p>{button('Обсудить обучение')}</div>{photo(image,alt,'inner-hero-photo',caption,True)}</section><nav class="page-nav" aria-label="Содержание страницы"><div class="shell">{''.join(f'<a href="#{i}">{t}</a>' for i,t in links)}</div></nav>'''

def feature(title,paras,image,alt,section_id='',reverse=False,caption='Иллюстрация учебного формата',extra=''):
    return f'<section class="shell section editorial-feature {"reverse" if reverse else ""}"'+(f' id="{section_id}"'if section_id else '')+f'><div class="feature-copy"><h2>{title}</h2>'+''.join(f'<p>{p}</p>'for p in paras)+extra+'</div>'+photo(image,alt,'feature-photo',caption)+'</section>'

def detail_block(title,paragraphs,section_id='',extra=''):
    return f'<section class="shell section reading-section"'+(f' id="{section_id}"'if section_id else '')+f'><h2>{title}</h2><div class="prose">'+''.join(f'<p>{p}</p>'for p in paragraphs)+extra+'</div></section>'

def price_table():
    rows=[('Один учебный день','4 часа + 30 минут перерыва','4 часа','3 600 ₽'),('Одна неделя','4 учебных дня','16 часов','14 400 ₽'),('Две недели','8 учебных дней','32 часа','28 800 ₽'),('Четыре недели','16 учебных дней','64 часа','57 600 ₽')]
    return '<div class="price-table-wrap"><table class="price-table"><caption class="sr-only">Стоимость обучения при цене 900 рублей за час</caption><thead><tr><th scope="col">Период</th><th scope="col">Практика</th><th scope="col">Стоимость</th></tr></thead><tbody>'+''.join(f'<tr><td><b>{a}</b><span>{b}</span></td><td>{c}</td><td>{d}</td></tr>'for a,b,c,d in rows)+'</tbody></table><p class="section-note">Месячный пакет в расчёте — ровно четыре учебные недели. Общая продолжительность программы определяется индивидуально.</p></div>'

def small_cta(title,copy,href,label):
    return f'<aside class="shell related-cta"><div><h2>{title}</h2><p>{copy}</p></div>{button(label,href)}</aside>'

home=f'''<section class="world-hero" aria-labelledby="home-heading"><img class="world-panorama" src="{PHOTO}world-panorama.jpg" alt="Художественная панорама городов мира" width="2048" height="1200" fetchpriority="high"><div class="world-sky"></div><div class="shell hero-content"><h1 id="home-heading">Большие планы.<br>Язык к сроку.</h1><p>Иностранные языки экстерном в Москва-Сити.<br>Для переезда, учёбы и работы — к вашему сроку.</p>{button('Подобрать программу','#application')}</div><div class="shell hero-bottom"><p>Учимся здесь.<br><span>Говорим с целым миром.</span></p><div class="hero-facts"><span>4 часа в день</span><span>4 дня в неделю</span><span>До 8 человек</span></div></div></section>
<section class="intro-section round-section"><div class="shell intro-grid"><div><h2>Язык нужен<br>не когда-нибудь.<br><span>А к вашей дате.</span></h2><p>Поступили в Италию, а до отлёта полгода? Планируете переезд или новую работу? Начнём с вашей цели и выстроим интенсивное обучение вокруг неё.</p><div class="goal-links"><a href="admission.html#goals">Переезд {ARROW}</a><a href="admission.html#goals">Поступление {ARROW}</a><a href="admission.html#goals">Работа и карьера {ARROW}</a><a href="admission.html#goals">Экзамен {ARROW}</a></div></div><div class="intro-note"><h3>Важен не пройденный<br>учебник.<br>Важен ваш следующий шаг.</h3><p>Учимся понимать, отвечать, обсуждать и пользоваться языком в живых ситуациях. В небольших группах, с личным вниманием преподавателя.</p><a class="text-link" href="format.html">Познакомиться с форматом {ARROW}</a></div></div></section>'''
home+=languages_section()+format_feature()
home+=feature('В группе.<br>С вниманием к вам.',['До 8 человек — достаточно для диалога, парной работы и общей динамики. И достаточно мало, чтобы преподаватель видел каждого.','Дети, подростки и взрослые занимаются отдельно. У каждой группы своя программа, точка старта и темп.'],PHOTO+'study-detail.jpg','Иллюстрация парной работы на занятии',extra=f'<div class="age-links"><a href="format.html#adults">Взрослые {ARROW}</a><a href="format.html#teenagers">Подростки {ARROW}</a><a href="format.html#children">Дети {ARROW}</a></div>')
home+=schedule_cards()
home+='<section class="pale-section round-section"><div class="shell section">'+calculator()+'</div></section>'
home+=feature('Сначала познакомиться.<br>Потом решить.',['Пробный урок проходит онлайн, один на один с вашим преподавателем. Он узнаёт вашу цель, темп и особенности — вы знакомитесь с его подходом.','Комфортно ли говорить? Понятно ли объяснение? Хочется ли продолжить? Вы принимаете решение на собственном опыте.'],PHOTO+'teacher-online.jpg','Иллюстрация индивидуального онлайн-знакомства с преподавателем',reverse=True,extra=button('О собеседовании и пробном уроке','interview.html','button-outline'))
home+='<section class="shell section start-section">'+section_title('От первого разговора<br>до первого занятия.','Понятный путь, на котором есть время задать вопросы и сделать свой выбор.',('admission.html','Всё о поступлении'))+admissions_steps()+'</section>'
home+=faq(GENERAL_FAQ)

admission=innerhero('Поступление.<br>Начнём с вас.','Ваша история, цель и сроки — отправная точка. Познакомимся, обсудим интенсив и подберём программу, с которой понятно, куда двигаться.',PHOTO+'group-practice.jpg','Иллюстрация знакомства и общения в языковой школе',[('goals','Ваша цель'),('path','Как поступить'),('levels','Уровень и группа'),('questions','Вопросы')],'Иллюстрация учебного формата')
admission+=feature('Для чего вам язык?',['Переезд, работа, экзамен, поступление или давняя мечта заговорить — сначала мы внимательно выслушаем вас. Нам важно понять, какие ситуации ждут вас впереди и когда язык должен стать рабочим инструментом.','Обсудим вашу готовность к интенсиву: четыре часа в день, четыре дня в неделю. Это серьёзное погружение, и его ритм должен подходить вашей жизни.'],LANGUAGES[0]['photo'],'Итальянский город у моря','goals',caption='Италия — одно из направлений ваших будущих планов')
